mapper.update:
update my_mall.shopping_cart


        goods_count=#{goodsCount},


        update_time=#{updateTime}


where id=#{id}

mapper.select:
select sc.id as cartitemId,sc.goods_count,g.cover_img,sc.goods_id, g.name as goodsName,g.selling_price
       from my_mall.shopping_cart as sc left join my_mall.goods as g on sc.goods_id=g.id
where sc.id=#{cartItemId}
